import{GARDEN_CONFIG as u}from"./config.min.js";export const SPRING="spring",SUMMER="summer",AUTUMN="autumn",WINTER="winter",HOURS_PER_DAY=24;export function hourAt(r,t=u.clock.cycleSeconds){if(!(t>0))return 0;const o=r/t;return(o-Math.floor(o))*HOURS_PER_DAY}export function yearAt(r,t=u.clock.cycleSeconds){return t>0?r/t:0}export function startSeconds(r=u.clock){return wrapHour(r.startHour||0)/HOURS_PER_DAY*r.cycleSeconds}export function yearPhaseAt(r){return wrapHour(r)/HOURS_PER_DAY}export function wrapHour(r){const t=r%HOURS_PER_DAY;return t<0?t+HOURS_PER_DAY:t}export function seasonAt(r,t=u.season.boundaries){const o=wrapHour(r);return o>t.spring&&o<=t.summer?SPRING:o>t.summer&&o<=t.autumn?SUMMER:o>t.autumn&&o<=t.winter?AUTUMN:WINTER}export function seasonPhaseAt(r,t=u.season.boundaries){const o=wrapHour(r),e=seasonAt(o,t),n={[SPRING]:t.spring,[SUMMER]:t.summer,[AUTUMN]:t.autumn,[WINTER]:t.winter},s=HOURS_PER_DAY/4;return wrapHour(o-n[e])/s}export function inThirstWindow(r,t=u.season.thirst){const o=wrapHour(r);return o>t.start&&o<=t.end}export function solarAt(r,t=u.sun){const o=wrapHour(r),e=t.maxElevation*Math.sin((o-6)*Math.PI/12),n=(o-12)*15;return{elevation:e,azimuth:n}}export function lunarAt(r,t=u.sun){const o=solarAt(r,t);return{elevation:-o.elevation,azimuth:o.azimuth+180}}export function snowCoverageAt(r,t=u.season){const o=t.snow,e=t.boundaries.winter,n=wrapHour(r-e),s=p=>wrapHour(p-e),i=s(o.firstFlakes),a=s(o.accumulatedBy),c=s(o.holdUntil),f=s(o.meltBy);return n<i?0:n<a?smoothstep((n-i)/(a-i)):n<c?1:n<f?1-smoothstep((n-c)/(f-c)):0}export function isSnowingAt(r,t=u.season){const o=t.snow,e=t.boundaries.winter,n=wrapHour(r-e);return n>=wrapHour(o.firstFlakes-e)&&n<wrapHour(o.holdUntil-e)}export function phenologyAt(r,t=!1,o=u.season){const e=wrapHour(r),n=o.phenology;if(t)return{bud:0,leaf:1,color:Math.max(0,-Math.sin((e-6)*Math.PI/12))*n.evergreenWinterFade,drop:0};if(e>n.dropEnd||e<=n.budStart)return{bud:0,leaf:0,color:1,drop:1};if(e<=n.budEnd){const i=(e-n.budStart)/(n.budEnd-n.budStart);return{bud:smoothstep(i),leaf:i*n.budLeafSize,color:0,drop:0}}if(e<=n.expandEnd){const i=(e-n.budEnd)/(n.expandEnd-n.budEnd);return{bud:1,leaf:n.budLeafSize+(1-n.budLeafSize)*smoothstep(i),color:0,drop:0}}if(e<=n.turnStart)return{bud:1,leaf:1,color:0,drop:0};if(e<=n.turnEnd){const i=(e-n.turnStart)/(n.turnEnd-n.turnStart);return{bud:1,leaf:1,color:smoothstep(i),drop:0}}const s=(e-n.dropStart)/(n.dropEnd-n.dropStart);return{bud:1,leaf:1,color:1,drop:smoothstep(clamp01(s))}}export function fruitStageAt(r,t,o=u.garden.fruit){if(!t)return{bloom:0,size:0,ripe:0,drop:1};const e=b=>wrapHour(b-t.bloomStart),n=e(r),s=e(t.bloomFull),i=e(t.bloomFade),a=e(t.bloomEnd),c=e(t.setEnd),f=e(t.swellEnd),p=e(t.ripenEnd),m=e(t.holdEnd),l=e(t.dropEnd);let d=0;if(n<s?d=smoothstep(n/s):n<i?d=1:n<a&&(d=1-smoothstep((n-i)/(a-i))),t.dropEnd==null)return{bloom:d,size:0,ripe:0,drop:1};let E=0;n>=a&&n<c?E=o.setSize*smoothstep((n-a)/(c-a)):n>=c&&n<l&&(E=o.setSize+(1-o.setSize)*smoothstep(Math.min(1,(n-c)/(f-c))));let S=0;n>=f&&n<l&&(S=smoothstep(Math.min(1,(n-f)/(p-f))));let x=0;return n>=m&&n<l?x=smoothstep((n-m)/(l-m)):n>=l&&(x=1),{bloom:d,size:E,ripe:S,drop:x}}export function fruitWords(r,t=!0){return r?r.bloom>.15?"In blossom":!t||r.drop>=1||r.size<=.02?"":r.drop>.05?"Dropping its fruit":r.ripe>.85?"Fruit ripe":r.ripe>.05?"Fruit ripening":"Fruit swelling":""}export function clamp01(r){return r<0?0:r>1?1:r}export function smoothstep(r){const t=clamp01(r);return t*t*(3-2*t)}
